const defaultState={current:'Robby',portfolio:'Robby',progress:[],entries:[],drafts:{}};
let state=loadState();let currentSubject='reading';let currentLesson=null;let speech=null;
function loadState(){try{return {...defaultState,...JSON.parse(localStorage.getItem('starbound-state')||'{}')}}catch{return {...defaultState}}}
function saveState(){localStorage.setItem('starbound-state',JSON.stringify(state))}
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function today(){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date())}
function updateHeader(){const p=$('#profileButton');p.innerHTML=`<span class="mini-avatar">${state.current[0]}</span>${state.current}⌄`;$('#todayLabel').textContent=`Today · ${today()}`;$('#learnerNote').textContent=state.current==='Robby'?'Sound it out, test an idea, and collect a star.':'Race through a story, find the hidden structure, and prove your thinking.';$('#orbCount').textContent=state.progress.filter(x=>x.learner===state.current).length}
function setView(name){$$('.view').forEach(v=>v.classList.remove('active'));$(`#${name}View`).classList.add('active');$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='log')renderLog();if(name==='portfolio')renderPortfolio();scrollTo({top:0,behavior:'smooth'})}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
$('#profileButton').addEventListener('click',()=>$('#profileDialog').showModal());$$('[data-profile]').forEach(b=>b.addEventListener('click',()=>{state.current=b.dataset.profile;saveState();updateHeader();if($('#subjectView').classList.contains('active'))openSubject(currentSubject)}));
$$('[data-subject]').forEach(b=>b.addEventListener('click',()=>openSubject(b.dataset.subject)));
function openSubject(subject){currentSubject=subject;const s=SUBJECTS[subject];$('#subjectKicker').textContent=s.kicker;$('#subjectTitle').textContent=s.title;$('#subjectIntro').textContent=s.intro;$('#subjectGlyph').textContent=s.glyph;$('#subjectGlyph').style.background=`${s.color}22`;const lessons=LESSONS[state.current][subject];$('#lessonGrid').innerHTML=lessons.map((l,i)=>{const done=state.progress.some(p=>p.learner===state.current&&p.lessonId===l.id);return `<button class="lesson-card" style="--accent:${s.color}" data-lesson="${l.id}"><span class="number">${i+1}</span><h2>${l.title}</h2><p>${l.desc}</p><footer><span>${l.skill.split('·')[0]}</span><span class="${done?'done-stamp':''}">${done?'✓ complete':'start ›'}</span></footer></button>`}).join('');$$('[data-lesson]').forEach(b=>b.addEventListener('click',()=>openLesson(b.dataset.lesson)));setView('subject')}
function findLesson(id){return Object.values(LESSONS[state.current]).flat().find(l=>l.id===id)}
function openLesson(id){currentLesson=findLesson(id);const l=currentLesson;let body='';if(l.type==='reader')body=readerTemplate(l);if(l.type==='blend')body=blendTemplate(l);if(l.type==='choice')body=choiceTemplate(l);if(l.type==='writing')body=writingTemplate(l);if(l.type==='compare')body=compareTemplate(l);if(l.type==='equation')body=equationTemplate(l);if(l.type==='force')body=forceTemplate(l);if(l.type==='music')body=musicTemplate(l);if(l.type==='spanish')body=spanishTemplate(l);$('#lessonContent').innerHTML=`<div class="lesson-shell"><button class="dialog-close" data-close="lessonDialog">×</button><p class="soft-label">${SUBJECTS[currentSubject].kicker} mission</p><h2>${l.title}</h2><p class="skill">Target: ${l.skill}</p><div class="lesson-body">${body}</div><div class="lesson-footer"><span id="answerStatus">Try it, explain it, then log it.</span><button class="complete-btn" id="completeLesson">Complete mission +1 ✦</button></div></div>`;bindLesson();$('#lessonDialog').showModal();if(l.type==='force'||l.type==='music')window.dispatchEvent(new CustomEvent('starbound:lab',{detail:{type:l.type}}))}
function readerTemplate(l){const words=l.data.text.split(/(\s+)/).map((w,i)=>/^\s+$/.test(w)?w:`<span data-word="${i}">${esc(w)}</span>`).join('');return `<div class="read-controls"><button id="readAloud">▶ Read aloud</button><button id="stopRead">■ Stop</button><label>Speed <select id="speechRate"><option value="0.75">Slow</option><option value="0.95" selected>Steady</option><option value="1.15">Fast</option></select></label></div><div class="reader-text" id="readerText" data-plain="${esc(l.data.text)}">${words}</div>${questionBlock(l.data)}`}
function blendTemplate(l){return `<p>${l.data.question}</p><div class="blend-board">${l.data.parts.map((p,i)=>`<button class="sound-chip" data-sound="${p}">${p}</button>${i<l.data.parts.length-1?'<span class="operator">+</span>':''}`).join('')}<span class="operator">=</span><button class="sound-chip" data-sound="${l.data.word}">?</button></div><div class="choices"><button class="choice" data-answer="true">${l.data.word}</button><button class="choice" data-answer="false">ran</button></div>`}
function questionBlock(d){return `<p><b>${d.q}</b></p><div class="choices">${d.choices.map((c,i)=>`<button class="choice" data-answer="${i===d.answer}">${esc(c)}</button>`).join('')}</div>`}
function choiceTemplate(l){return `<div class="reader-text">${esc(l.data.text)}</div>${questionBlock(l.data)}`}
function writingTemplate(l){return `<p><b>${l.data.prompt}</b></p><textarea class="writing-box" id="writingDraft" placeholder="${esc(l.data.starter)}">${esc(state.drafts[l.id]||'')}</textarea><div class="checklist">${l.data.checks.map(c=>`<label><input type="checkbox"> ${c}</label>`).join('')}</div><button class="lesson-action" id="saveDraft">Save writing sample</button>`}
function compareTemplate(l){const opts=l.data.advanced?['A = B + C','A + B = C','A = B - C']:['<','=','>'];return `<p><b>${l.data.q}</b></p><div class="math-bars"><div class="bar a">${l.data.advanced?'A':''}</div><div class="bar b">${l.data.advanced?'B':''}</div><div class="symbol-buttons">${opts.map(x=>`<button class="choice" data-value="${x}" data-answer="${x===l.data.answer}">${x}</button>`).join('')}</div></div>`}
function equationTemplate(l){return `<p><b>${l.data.q}</b></p><label>Your answer <input id="numberAnswer" type="number" inputmode="numeric"></label> <button class="lesson-action" id="checkNumber">Check relationship</button>`}
function forceTemplate(){return `<p>Predict first: how will a stronger push change the ball's motion?</p><div class="force-lab"><canvas class="three-stage" id="lab3d" aria-label="Interactive 3D force experiment"></canvas><label>Push strength <input id="forceRange" type="range" min="1" max="5" value="1"></label><button class="lesson-action" id="testForce">Test push</button><p id="forceResult">Set a strength and run the test.</p></div>`}
function musicTemplate(l){return `<p>Tap the notes, then turn beats on and off to invent a pattern.</p><div class="music-lab"><canvas class="three-stage" id="lab3d" aria-label="3D music visualizer"></canvas><div class="note-keys">${[['C',261.63],['D',293.66],['E',329.63],['G',392],['A',440]].map(([n,f])=>`<button class="note-key" data-note="${f}">${n}</button>`).join('')}</div><div class="rhythm-row">${l.data.pattern.map((on,i)=>`<button class="beat ${on?'on':''}" data-beat="${i}">${i+1}</button>`).join('')}</div><button class="lesson-action" id="playPattern">▶ Play my rhythm</button></div>`}
function spanishTemplate(l){return `<div class="spanish-card"><p class="phrase">${esc(l.data.phrase)}</p><p>${esc(l.data.meaning)}</p><button class="speak-spanish" id="speakSpanish">▶ Escuchar / Listen</button></div>${questionBlock(l.data)}`}
function bindLesson(){$$('[data-close]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.close).close()));$$('.choice[data-answer]').forEach(b=>b.addEventListener('click',()=>{const ok=b.dataset.answer==='true';b.classList.add(ok?'correct':'wrong');$('#answerStatus').textContent=ok?'Correct—now explain why.':'Not yet. Look for the evidence and try again.'}));$$('[data-sound]').forEach(b=>b.addEventListener('click',()=>speakText(b.dataset.sound,.65)));$('#readAloud')?.addEventListener('click',readAloud);$('#stopRead')?.addEventListener('click',stopSpeech);$('#speakSpanish')?.addEventListener('click',()=>speakText(currentLesson.data.phrase,.8,'es-US'));$$('[data-beat]').forEach(b=>b.addEventListener('click',()=>b.classList.toggle('on')));$$('[data-note]').forEach(b=>b.addEventListener('click',()=>playTone(Number(b.dataset.note),.35)));$('#playPattern')?.addEventListener('click',playPattern);$('#saveDraft')?.addEventListener('click',()=>{state.drafts[currentLesson.id]=$('#writingDraft').value.trim();saveState();$('#answerStatus').textContent='Writing saved to the portfolio.';showToast('Writing sample saved')});$('#checkNumber')?.addEventListener('click',()=>{const ok=Number($('#numberAnswer').value)===currentLesson.data.a;$('#answerStatus').textContent=ok?'Correct. Can you show it with a drawing or equation?':'Try building up or counting back to find the difference.'});$('#testForce')?.addEventListener('click',()=>{const f=Number($('#forceRange').value);window.dispatchEvent(new CustomEvent('starbound:force',{detail:{strength:f}}));$('#forceResult').textContent=`Evidence: strength ${f} moved the sphere ${f*2} distance units. A stronger push caused a larger change in motion.`;$('#answerStatus').textContent='Test complete. What pattern did you observe?'});$('#completeLesson').addEventListener('click',completeLesson)}
function speakText(text,rate=.95,lang='en-US'){stopSpeech();speech=new SpeechSynthesisUtterance(text);speech.rate=rate;speech.pitch=1.05;speech.lang=lang;speechSynthesis.speak(speech)}
function playTone(freq,duration=.3,delay=0){const audio=playTone.ctx||(playTone.ctx=new(window.AudioContext||window.webkitAudioContext)());const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(0,audio.currentTime+delay);gain.gain.linearRampToValueAtTime(.2,audio.currentTime+delay+.02);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+delay+duration);osc.connect(gain).connect(audio.destination);osc.start(audio.currentTime+delay);osc.stop(audio.currentTime+delay+duration);window.dispatchEvent(new CustomEvent('starbound:note',{detail:{frequency:freq,delay}}))}
function playPattern(){const beats=$$('.beat').map(b=>b.classList.contains('on'));beats.forEach((on,i)=>{if(on)playTone([261.63,329.63,392,523.25][i],.25,i*.42)});$('#answerStatus').textContent='You created and performed a rhythm pattern.'}
function readAloud(){const el=$('#readerText'),text=el.dataset.plain;stopSpeech();speech=new SpeechSynthesisUtterance(text);speech.rate=Number($('#speechRate').value);speech.onboundary=e=>{const spans=$$('#readerText span');spans.forEach(s=>s.classList.remove('speaking'));let chars=0;for(const span of spans){chars+=span.textContent.length+1;if(chars>e.charIndex){span.classList.add('speaking');break}}};speech.onend=()=>$$('#readerText span').forEach(s=>s.classList.remove('speaking'));speechSynthesis.speak(speech)}
function stopSpeech(){speechSynthesis.cancel();speech=null}
function completeLesson(){const l=currentLesson;if(!state.progress.some(p=>p.learner===state.current&&p.lessonId===l.id)){state.progress.unshift({id:crypto.randomUUID(),learner:state.current,subject:currentSubject,lessonId:l.id,title:l.title,skill:l.skill,date:new Date().toISOString(),kind:'mission'});saveState()}stopSpeech();$('#lessonDialog').close();updateHeader();openSubject(currentSubject);showToast('Mission logged — star earned!')}
function statsFor(entries){return Object.keys(SUBJECTS).map(s=>({s,n:entries.filter(e=>e.subject===s).length}))}
function renderLog(){const all=[...state.progress,...state.entries].sort((a,b)=>new Date(b.date)-new Date(a.date));const learner=$('#logLearner').value,subject=$('#logSubject').value;const visible=all.filter(e=>(learner==='all'||e.learner===learner)&&(subject==='all'||e.subject===subject));$('#summaryStats').innerHTML=statsFor(all).map(x=>`<div class="stat" style="--accent:${SUBJECTS[x.s].color}"><strong>${x.n}</strong><span>${SUBJECTS[x.s].kicker} records</span></div>`).join('');$('#activityLog').innerHTML=visible.length?visible.map(e=>`<div class="log-row"><time>${new Date(e.date).toLocaleDateString()}</time><span class="subject-pill">${e.subject}</span><div><b>${esc(e.title||'Family learning note')}</b><p>${esc(e.note||e.skill||'')}</p></div><small>${e.learner}</small></div>`).join(''):'<div class="empty">No records match these filters yet.</div>'}
$('#logLearner').addEventListener('change',renderLog);$('#logSubject').addEventListener('change',renderLog);$('#addEntryBtn').addEventListener('click',()=>{$('#entryForm [name=learner]').value=state.current;$('#entryDialog').showModal()});$('#entryForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);state.entries.unshift({id:crypto.randomUUID(),learner:d.get('learner'),subject:d.get('subject'),title:'Family learning note',note:d.get('note'),skill:d.get('skills'),date:new Date().toISOString(),kind:'note'});saveState();e.target.reset();$('#entryDialog').close();renderLog();showToast('Learning note saved')});
function renderPortfolio(){const who=state.portfolio;$$('[data-portfolio]').forEach(b=>b.classList.toggle('selected',b.dataset.portfolio===who));const records=[...state.progress,...state.entries].filter(e=>e.learner===who).sort((a,b)=>new Date(a.date)-new Date(b.date));const drafts=Object.entries(state.drafts).filter(([id,v])=>v&&Object.values(LESSONS[who]).flat().some(l=>l.id===id));const sections=Object.keys(SUBJECTS).map(subject=>{const r=records.filter(e=>e.subject===subject);const samples=subject==='writing'?drafts.map(([id,text])=>{const l=Object.values(LESSONS[who]).flat().find(x=>x.id===id);return `<div class="work-sample"><b>${esc(l?.title||'Writing sample')}</b>\n${esc(text)}</div>`}).join(''):'';return `<section class="portfolio-section"><h3>${SUBJECTS[subject].glyph} ${SUBJECTS[subject].kicker}</h3><p><b>${r.length} documented learning ${r.length===1?'experience':'experiences'}</b></p>${r.slice(-5).map(e=>`<div class="work-sample"><b>${new Date(e.date).toLocaleDateString()} · ${esc(e.title||'Learning note')}</b>\n${esc(e.note||e.skill||'')}</div>`).join('')}${samples||(!r.length?'<p class="empty">Future work will appear here.</p>':'')}</section>`}).join('');$('#portfolioPaper').innerHTML=`<header class="portfolio-cover"><div><p>Starbound Academy</p><h2>${who}'s learning portfolio</h2><p>2026–2027 · Year-to-date</p></div><div><b>${records.length}</b><br>documented experiences</div></header><section class="portfolio-section"><h3>Learning story</h3><p>${who} is building a record of reading, writing, mathematical reasoning, and scientific investigation. This portfolio includes completed digital missions and family observations from hands-on learning.</p></section>${sections}`}
$$('[data-portfolio]').forEach(b=>b.addEventListener('click',()=>{state.portfolio=b.dataset.portfolio;saveState();renderPortfolio()}));$('#printBtn').addEventListener('click',()=>window.print());
$('#exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`starbound-academy-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)});$('#importInput').addEventListener('change',async e=>{try{const data=JSON.parse(await e.target.files[0].text());state={...defaultState,...data};saveState();updateHeader();renderLog();showToast('Backup imported')}catch{showToast('That backup could not be read.')}});
updateHeader();renderPortfolio();if(!localStorage.getItem('starbound-welcomed')){$('#profileDialog').showModal();localStorage.setItem('starbound-welcomed','yes')}
